 void night(){if(!ScrollService.connected){Toast.makeText(this,"Activez le service d’accessibilité",Toast.LENGTH_LONG).show();return;}new TimePickerDialog(this,(v,hour,minute)->{java.util.Calendar c=java.util.Calendar.getInstance();c.set(java.util.Calendar.HOUR_OF_DAY,hour);c.set(java.util.Calendar.MINUTE,minute);c.set(java.util.Calendar.SECOND,0);c.set(java.util.Calendar.MILLISECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(java.util.Calendar.DAY_OF_YEAR,1);nightAt=c.getTimeInMillis();p.edit().putInt("nightHour",hour).putInt("nightMinute",minute).apply();new AlertDialog.Builder(this).setTitle("Armer le mode nocturne").setMessage("Laissez le téléphone en charge, déverrouillé, sur les résultats Ricardo. Autorisez la capture maintenant. Une seule session sera lancée à "+String.format(java.util.Locale.US,"%02d:%02d",hour,minute)+".").setNegativeButton("Annuler",null).setPositiveButton("Armer",(d,k)->{if(RecordingService.instance!=null)RecordingService.instance.finishCapture();startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),42);}).show();},p.getInt("nightHour",3),p.getInt("nightMinute",0),true).show();}
 void choice(String title,String key,String[] values,int def){root.addView(label(title,16,fg));Spinner s=new Spinner(this);s.setBackground(shape(card,10));s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setSelection(p.getInt(key,def));root.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){if(v instanceof TextView)((TextView)v).setTextColor(fg);p.edit().putInt(key,i).apply();}});}
 void settings(){new AlertDialog.Builder(this).setTitle("Paramètres").setItems(new String[]{"Thème système","Thème sombre","Thème clair","Accessibilité","Mode continu","Mode par étapes"},(d,i)->{if(i<3){p.edit().putInt("theme",i).apply();render();}else if(i==3)startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));else p.edit().putInt("mode",i==4?1:0).apply();}).show();}
 void shareLast(){String value=p.getString("lastVideo","");if(value.isEmpty()){Toast.makeText(this,"Aucune vidéo",Toast.LENGTH_SHORT).show();return;}Uri u=Uri.parse(value);Intent i=new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("Vidéo Ricardo",u));startActivity(Intent.createChooser(i,"Partager la vidéo"));}
 void videos(){java.util.ArrayList<Uri> uris=new java.util.ArrayList<>();java.util.ArrayList<String> names=new java.util.ArrayList<>();try(Cursor c=getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name"},"relative_path LIKE ? AND is_pending=0",new String[]{"Download/Ricardo AutoScroll%"}, "date_added DESC")){while(c!=null&&c.moveToNext()){uris.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,c.getLong(0)));names.add(c.getString(1));}}catch(Exception e){Toast.makeText(this,"Lecture indisponible",Toast.LENGTH_SHORT).show();}new AlertDialog.Builder(this).setTitle("Mes enregistrements").setItems(names.toArray(new String[0]),(d,i)->{Uri u=uris.get(i);new AlertDialog.Builder(this).setTitle(names.get(i)).setItems(new String[]{"Visionner","Partager","Supprimer"},(a,k)->{if(k==2){new AlertDialog.Builder(this).setMessage("Supprimer cette vidéo ?").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(x,y)->{try{getContentResolver().delete(u,null,null);}catch(Exception e){Toast.makeText(this,"Suppression impossible",Toast.LENGTH_SHORT).show();}}).show();}else{Intent in=new Intent(k==0?Intent.ACTION_VIEW:Intent.ACTION_SEND);if(k==0)in.setDataAndType(u,"video/mp4");else in.setType("video/mp4").putExtra(Intent.EXTRA_STREAM,u);in.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(in,null));}catch(ActivityNotFoundException e){Toast.makeText(this,"Aucune application compatible",Toast.LENGTH_SHORT).show();}}}).show();}).setPositiveButton("Fermer",null).show();}
